INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('63955076', 63955076, 'analyze_legacy', 'Kementerian Agraria dan Tata Ruang/BPN', 'central', 'Kantor Pertanahan KABUPATEN PIDIE JAYA', 'Belanja Barang Persediaan Barang Konsumsi', 'Barang', 'Pengadaan Langsung', 'Aceh, Pidie Jaya (Kab.)', 500000, 'January 2026', 'APBN - PNBP (D)', 1, 1, '1 paket', 'Kegiatan Konsultasi Kepegawaian dilaksanakan untuk mendukung tertib administrasi dan kepatuhan terhadap peraturan perundang-undangan di bidang kepegawaian, serta memberikan kepastian dalam pengelolaan sumber daya manusia aparatur. Ruang lingkup kegiatan meliputi: 1. Konsultasi kebijakan dan regulasi kepegawaian. 2. Klarifikasi permasalahan administrasi dan status kepegawaian. 3. Koordinasi dengan instansi pembina dan unit terkait. 4. Pemberian rekomendasi penyelesaian permasalahan kepegawaian. Kegiatan ini bertujuan untuk meningkatkan kualitas pengelolaan kepegawaian, kelancaran pelayanan administrasi pegawai, serta mendukung pelaksanaan tugas dan fungsi satuan kerja.', 'KONSULTASI KEPEGAWAIAN Konsultasi Regulasi Kepegawaian Pemberian penjelasan dan konsultasi terkait peraturan perundang-undangan di bidang kepegawaian. Pembaruan informasi kebijakan kepegawaian sesuai ketentuan yang berlaku. Pendampingan Administrasi Kepegawaian Pendampingan pengelolaan administrasi kepegawaian pegawai. Klarifikasi status dan dokumen kepegawaian sesuai kebutuhan satuan kerja. Koordinasi dengan Instansi Pembina Koordinasi dengan instansi pembina kepegawaian dan unit terkait. Penyampaian dan penindaklanjutan hasil konsultasi. Penyelesaian Permasalahan Kepegawaian Analisis permasalahan kepegawaian yang dihadapi. Pemberian rekomendasi solusi sesuai ketentuan yang berlaku. Dokumentasi dan Pelaporan Penyusunan dokumentasi hasil konsultasi kepegawaian. Penyampaian laporan pelaksanaan kegiatan konsultasi kepegawaian. Standar Pelaksanaan Mengacu pada peraturan perundang-undangan di bidang kepegawaian. Dilaksanakan secara profesional, akuntabel, dan tepat waktu. Hasil yang Diharapkan Terwujudnya tertib administrasi kepegawaian. Meningkatnya kepastian dan kualitas pengelolaan kepegawaian satuan kerja.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 1253998);
