INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('63955473', 63955473, 'analyze_legacy', 'Kementerian Agraria dan Tata Ruang/BPN', 'central', 'Kantor Pertanahan KABUPATEN PIDIE JAYA', 'Penyusunan Dokumen SAKIP', 'Barang', 'Pengadaan Langsung', 'Aceh, Pidie Jaya (Kab.)', 500000, 'January 2026', 'APBN - PNBP (D)', 1, 1, '1 Paket', 'Kegiatan penyusunan Dokumen SAKIP dilaksanakan untuk mendukung terselenggaranya akuntabilitas kinerja instansi pemerintah melalui penyusunan dokumen perencanaan, pengukuran, pelaporan, dan evaluasi kinerja yang sistematis dan sesuai ketentuan peraturan perundang-undangan. Ruang lingkup kegiatan meliputi: 1. Pengumpulan dan pengolahan data kinerja. 2. Penyusunan dan/atau penyempurnaan dokumen SAKIP. 3. Sinkronisasi dokumen perencanaan dan pelaporan kinerja. 4. Penyusunan laporan kinerja sebagai bentuk pertanggungjawaban instansi.', '1. Jenis Dokumen yang Disusun o Dokumen Perencanaan Kinerja (Renstra/Renja/PK). o Dokumen Pengukuran dan Evaluasi Kinerja. o Laporan Kinerja Instansi Pemerintah (LKjIP). o Dokumen pendukung SAKIP lainnya sesuai ketentuan. 2. Metode Pelaksanaan o Koordinasi dengan unit kerja terkait. o Pengolahan dan analisis data kinerja. o Penyusunan dokumen sesuai pedoman SAKIP. 3. Standar dan Ketentuan o Mengacu pada peraturan perundang-undangan terkait SAKIP. o Memenuhi prinsip akuntabilitas, transparansi, dan keterukuran. 4. Hasil yang Diharapkan o Tersusunnya dokumen SAKIP yang lengkap dan berkualitas. o Meningkatnya nilai dan kualitas implementasi SAKIP satuan kerja.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 1255207);
