INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('63955430', 63955430, 'analyze_legacy', 'Kementerian Kesehatan', 'central', 'SEKRETARIAT DIREKTORAT JENDERAL FARMASI DAN ALAT KESEHATAN', 'Penyediaan Obat Filariasis dan Kecacingan Tahap II Tahun 2026', 'Barang', 'E-Purchasing', 'DKI Jakarta, Jakarta Selatan (Kota)', 37105493050, 'June 2026', 'APBN - RUPIAH MURNI (A)', 0, 1, '1 PT', 'Belanja Barang Bantuan Lainnya Untuk Diserahkan Kepada Masyarakat/Pemda dengan Menyediakan Obat Filariasis dan Kecacingan Tahun 2026 berupa Albendazole 400 mg, Albendazole Suspensi/Syrup dan Dietilkarbamazin Sitrat (DEC) 100 mg', 'Spesifikasi Obat Filariasis dan Kecacingan sebagai berikut : A. ALBENDAZOLE TABLET 400 mg : Deskripsi : Setiap tablet mengadung 400 mg zat aktif albendazole. 1. Sediaan Obat : Kaplet/tablet, bergaris tengah bisa di belah 2 2. Tablet/Kaplet Salut gula berasa manis 3. Beraroma buah – buahan Kemasan : 1. Kemasan obat : blister/strip 2. Masa kadaluarsa jika shelf life 24 bulan, maka masa kadaluarsa minimal 18 bulan, jika shelf life >24 bulan, maka masa kadaluarsa minimal 24 bulan. 3. Produk Obat wajib memiliki Nomor Ijin Edar (NIE) yang dikeluarkan oleh BPOM RI dan yang masih berlaku, dengan melampirkan NIE dan informasi produk 4. Dosis obat merujuk pada Permenkes No.15 tahun 2017 5. Informasi tentang obat tertulis dalam Bahasa Indonesia. B. ALBENDAZOLE SUSPENSI/SYRUP : Diskripsi : Setiap Botol mengandung suspensi yang berisi zat aktif Albendazole 400 mg / 10 ml atau 200 mg / 5ml 1. Sediaan suspensi 2. Berwarna 3. Beraroma dan berasa buah-buahan Kemasan : 1. Dalam botol plastik/kaca anti pecah 2. Masa kadaluarsa jika shelf life 24 bulan, maka masa kadaluarsa minimal 18 bulan, jika shelf life >24 bulan, maka masa kadaluarsa minimal 24 bulan. 3. Produk Obat wajib memiliki Nomor Ijin Edar (NIE) yang dikeluarkan oleh BPOM RI dan yang masih berlaku, dengan melampirkan NIE dan informasi produk 4. Dosis obat merujuk pada Permenkes No.15 tahun 2017 5. Informasi tentang obat tertulis dalam Bahasa Indonesia C. Dietilkarbamazin Sitrat (DEC) 100 mg : Deskripsi : Setiap tablet mengadung 100 mg zat aktif , Dietilkarbamazin Sitrat. 1. Sediaan Obat Kaplet/tablet Kemasan : 1. Kemasan obat : blister/strip 2. Masa kadaluarsa jika shelf life 24 bulan, maka masa kadaluarsa minimal 18 bulan, jika shelf life >24 bulan, maka masa kadaluarsa minimal 24 bulan. 3. Produk Obat wajib memiliki Nomor Ijin Edar (NIE) yang dikeluarkan oleh BPOM RI dan yang masih berlaku, dengan melampirkan NIE dan informasi produk 4. Dosis obat merujuk pada Permenkes No.15 tahun 2017 5. Informasi tentang obat tertulis dalam Bahasa Indonesia.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 1259077);
